package api

var sswCurriculumLogisticsWarehouseScenariosEnglish = map[examSSWEnglishKey]string{
	{field: "ssw.scenario", source: `Air mulai masuk di dekat rak dan beberapa kotak berada di lantai rendah.`}:                                                                                                      `Water is starting to enter near the racks, and several boxes are on a low level.`,
	{field: "ssw.scenario", source: `Catatan menunjukkan 30 unit, tetapi hitungan rak hanya 28.`}:                                                                                                                    `The record shows 30 units, but the shelf count is only 28.`,
	{field: "ssw.scenario", source: `Daftar memuat delapan paket, tetapi pengangkut akan membawa tujuh.`}:                                                                                                            `The list shows eight packages, but the carrier is taking seven.`,
	{field: "ssw.scenario", source: `Dua kotak terlihat sama tetapi mencantumkan nomor lot berbeda.`}:                                                                                                                `Two boxes look alike but show different lot numbers.`,
	{field: "ssw.scenario", source: `Instruksi meminta satu set tiga produk, tetapi jenis ketiga tidak ditemukan.`}:                                                                                                  `The instruction calls for a set of three products, but the third type cannot be found.`,
	{field: "ssw.scenario", source: `Lokasi yang ditunjuk penuh dan barang di rak memiliki label berbeda.`}:                                                                                                          `The assigned location is full, and the item on its shelf has a different label.`,
	{field: "ssw.scenario", source: `Nomor pesanan pada label kotak berbeda dari lembar penerimaan.`}:                                                                                                                `The order number on the box label differs from the receiving sheet.`,
	{field: "ssw.scenario", source: `Paket tertutup tetapi labelnya menunjukkan tujuan pelanggan lain.`}:                                                                                                             `A sealed package has a label for another customer's destination.`,
	{field: "ssw.scenario", source: `Palet retak membawa barang dan berada di jalur pemindahan.`}:                                                                                                                    `A cracked pallet carrying goods is in a material-handling route.`,
	{field: "ssw.scenario", source: `Pesanan meminta ukuran kecil, tetapi lokasi berisi kotak ukuran kecil dan besar.`}:                                                                                              `The order calls for the small size, but the location contains boxes in both small and large sizes.`,
	{field: "ssw.scenario", source: `Satu barang pada area pengepakan memiliki label lot berbeda dari daftar pesanan.`}:                                                                                              `An item in the packing area has a lot label that differs from the order list.`,
	{field: "ssw.scenario", source: `Satu kotak dari satu kelompok terlihat basah dan segelnya terbuka.`}:                                                                                                            `One box in a lot appears wet and its seal is open.`,
	{field: "ssw.response", source: `Cocokkan kode produk lengkap dengan pesanan sebelum mengambil. Jika jumlah ukuran kecil kurang, catat kekurangannya dan hubungi petugas, bukan mengganti dengan ukuran besar.`}: `Match the full product code to the order before picking. If there are too few small items, record the shortage and contact staff instead of substituting the large size.`,
	{field: "ssw.response", source: `Hentikan penutupan transaksi, hitung ulang, catat satu paket yang tertinggal, lalu koordinasikan apakah paket itu dikirim terpisah atau ditahan.`}:                              `Stop closing the transaction, recount, record the one package left behind, and coordinate whether it should be sent separately or held.`,
	{field: "ssw.response", source: `Hitung ulang dengan satuan yang benar, periksa apakah transaksi terbaru belum dicatat, lalu dokumentasikan 28 unit dan laporkan untuk pemeriksaan.`}:                            `Recount using the correct unit, check whether the latest transaction has not yet been recorded, then document the 28 units and report the discrepancy for review.`,
	{field: "ssw.response", source: `Jaga jarak dan beri tahu penanggung jawab. Minta petugas terlatih menentukan cara memindahkan palet serta lindungi jalur dari lalu lintas lain.`}:                               `Keep clear and notify the person in charge. Have trained staff decide how to move the pallet and keep other traffic out of the route.`,
	{field: "ssw.response", source: `Jangan menaruh barang di lokasi lain tanpa pencatatan. Tandai hambatan, laporkan kepada petugas, dan tunggu lokasi pengganti yang dicatat.`}:                                    `Do not place goods in another location without recording it. Flag the obstruction, notify staff, and wait for an alternate location to be recorded.`,
	{field: "ssw.response", source: `Laporkan lokasi dan keadaan kepada pengawas, ikuti rencana perlindungan gudang, serta catat setiap kotak yang dipindahkan dan lokasi barunya.`}:                                 `Report the location and conditions to a supervisor, follow the warehouse protection plan, and record every box moved and its new location.`,
	{field: "ssw.response", source: `Pisahkan kotak dari stok yang siap disimpan, catat jumlah dan kondisi yang terlihat, lalu laporkan agar petugas menentukan tindak lanjut.`}:                                     `Separate the box from stock ready for storage, record the quantity and visible condition, then report it so staff can decide the next step.`,
	{field: "ssw.response", source: `Simpan pada lokasi yang terpisah atau ditetapkan untuk masing-masing lot, lalu catat lokasi setiap kelompok agar penelusurannya tetap jelas.`}:                                  `Store each lot in a separate or designated location, then record where each group is kept to maintain traceability.`,
	{field: "ssw.response", source: `Tahan barang itu, cocokkan pesanan dan transaksi picking, lalu laporkan agar lot yang benar dipilih sebelum pengemasan.`}:                                                       `Hold the item, check the order and picking transaction, and report it so the correct lot can be selected before packing.`,
	{field: "ssw.response", source: `Tahan kotak pada area pemeriksaan, catat nomor yang terlihat dan dokumen terkait, lalu minta petugas mengonfirmasi pesanan sebelum barang masuk stok aktif.`}:                   `Hold the box in the inspection area, record the visible number and related documents, and ask staff to confirm the order before it enters active stock.`,
	{field: "ssw.response", source: `Tahan paket di area pemeriksaan, jangan menutupinya dengan label baru tanpa prosedur, dan minta label dikoreksi serta diverifikasi terhadap pesanan.`}:                          `Hold the package in the inspection area. Do not cover it with a new label outside procedure; request a corrected label and verify it against the order.`,
	{field: "ssw.response", source: `Tahan pembuatan set, catat produk yang ada dan yang kurang, lalu minta petugas menentukan apakah stok dicari atau pesanan ditunda.`}:                                            `Hold the kitting process, record which products are present and missing, and ask staff whether to locate stock or delay the order.`,
}
